import numpy as np
from math import comb
def _pmf_table(top, seed):
    rng = np.random.default_rng(seed)
    pmf = rng.random((5, 7)) ** 2
    pmf /= pmf.sum()
    table = np.zeros((top + 1, top + 1))
    for p in range(top + 1):
        for q in range(top + 1 - p):
            table[p, q] = sum(comb(i, p) * comb(j, q) * pmf[i, j] for i in range(5) for j in range(7))
    return table
def _poisson_table(top, a, b):
    from math import factorial
    table = np.zeros((top + 1, top + 1))
    for p in range(top + 1):
        for q in range(top + 1 - p):
            table[p, q] = a ** p / factorial(p) * b ** q / factorial(q)
    return table
def _digest(x):
    s = np.asarray(x, dtype=float)
    if s.shape != (3,):
        return -1.0
    return float(3.0 + 1.0e3 * s[0] + 7.0e1 * s[1] + 3.0e2 * s[2])
assert np.allclose(_digest(compute_transcript_conditioned_protein_statistics(_pmf_table(12, 3), 0)), target)

